-- DEMO: complete database setup for a NEW Supabase project.
-- Generated by scripts/build-setup-sql.ts. Paste into Supabase → SQL Editor → Run.
-- Run it once. To update an existing project later, run only the new migration files.

-- ═════ 20261118000001_schema.sql ═════
-- ═══════════════════════════════════════════════════════════════════════
-- DEMO — core schema
-- Guest-only storefront (no customer accounts, by decision 2026-11-18).
-- auth.users / profiles exist only for store staff (admin dashboard).
-- Spec tables carts, cart_items, wishlists, addresses and reviews are
-- intentionally omitted: they need customer accounts. Shipping addresses
-- are stored as a snapshot on each order.
-- ═══════════════════════════════════════════════════════════════════════

-- ───────────── types ─────────────
create type public.staff_role     as enum ('staff', 'admin');
create type public.order_status   as enum ('pending', 'confirmed', 'processing', 'shipped', 'delivered', 'cancelled', 'refunded');
create type public.payment_status as enum ('pending', 'paid', 'failed', 'refunded', 'cancelled');
create type public.payment_method as enum ('cod', 'bkash', 'nagad', 'stripe');

-- ───────────── helpers ─────────────
create or replace function public.set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- ───────────── staff profiles ─────────────
create table public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  full_name   text check (char_length(full_name) <= 120),
  role        public.staff_role,             -- null = no dashboard access
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- SECURITY DEFINER so it can read profiles regardless of the caller's RLS.
create or replace function public.is_staff() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role is not null)
$$;
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
$$;

-- New auth users get a profile with NO role. Roles are granted by an admin
-- (or by SQL for the first admin) — never self-assigned.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id) values (new.id) on conflict do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ───────────── catalogue ─────────────
create table public.categories (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name        text not null check (char_length(name) between 1 and 80),
  parent_id   uuid references public.categories (id) on delete set null,
  sort        int not null default 0,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table public.products (
  id              uuid primary key default gen_random_uuid(),
  legacy_id       text unique,                         -- id used by the demo catalogue (p1…)
  slug            text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name            text not null check (char_length(name) between 1 and 120),
  description     text not null default '',
  details         text[] not null default '{}',
  category_id     uuid not null references public.categories (id) on delete restrict,
  gender          text not null check (gender in ('women', 'men', 'unisex', 'kids')),
  colour          text not null,
  colour_hex      text not null check (colour_hex ~ '^#[0-9a-fA-F]{6}$'),
  price_bdt       int  not null check (price_bdt > 0),
  sale_price_bdt  int  check (sale_price_bdt is null or (sale_price_bdt > 0 and sale_price_bdt < price_bdt)),
  is_active       boolean not null default true,
  is_new          boolean not null default false,
  is_bestseller   boolean not null default false,
  popularity      int not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index products_category_idx on public.products (category_id) where is_active;
create index products_created_idx  on public.products (created_at desc) where is_active;

create table public.product_images (
  id               uuid primary key default gen_random_uuid(),
  product_id       uuid not null references public.products (id) on delete cascade,
  src              text not null,                      -- Storage path or /public path
  alt              text not null default '',
  fit              text not null default 'cover' check (fit in ('contain', 'cover')),
  object_position  text,
  sort             int not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index product_images_product_idx on public.product_images (product_id, sort);

create table public.product_variants (
  id                  uuid primary key default gen_random_uuid(),
  product_id          uuid not null references public.products (id) on delete cascade,
  size                text not null check (char_length(size) between 1 and 8),
  sku                 text not null unique check (sku ~ '^[A-Z0-9-]+$'),
  price_override_bdt  int check (price_override_bdt is null or price_override_bdt > 0),
  is_active           boolean not null default true,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (product_id, size)
);

create table public.inventory (
  variant_id           uuid primary key references public.product_variants (id) on delete cascade,
  quantity             int not null default 0 check (quantity >= 0),
  low_stock_threshold  int not null default 3 check (low_stock_threshold >= 0),
  updated_at           timestamptz not null default now()
);
create index inventory_low_idx on public.inventory (quantity) where quantity <= 3;

-- ───────────── commerce config ─────────────
create table public.shipping_zones (
  id             text primary key check (id ~ '^[a-z0-9-]+$'),
  label          text not null,
  fee_bdt        int not null check (fee_bdt >= 0),
  free_over_bdt  int check (free_over_bdt is null or free_over_bdt > 0),
  eta            text not null default '',
  is_active      boolean not null default true,
  sort           int not null default 0,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create table public.coupons (
  id                uuid primary key default gen_random_uuid(),
  code              text not null unique check (code = upper(code) and code ~ '^[A-Z0-9]{3,32}$'),
  kind              text not null check (kind in ('percent', 'fixed')),
  value             int  not null check (value > 0),
  min_subtotal_bdt  int  not null default 0 check (min_subtotal_bdt >= 0),
  max_discount_bdt  int  check (max_discount_bdt is null or max_discount_bdt > 0),
  usage_limit       int  check (usage_limit is null or usage_limit > 0),
  used_count        int  not null default 0 check (used_count >= 0),
  starts_at         timestamptz not null default now(),
  expires_at        timestamptz,
  is_active         boolean not null default true,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check (kind <> 'percent' or value <= 100),
  check (usage_limit is null or used_count <= usage_limit)
);

-- ───────────── orders ─────────────
create table public.orders (
  id                uuid primary key default gen_random_uuid(),
  order_number      text not null unique,
  idempotency_key   text unique check (char_length(idempotency_key) <= 64),
  status            public.order_status   not null default 'pending',
  payment_method    public.payment_method not null,
  payment_status    public.payment_status not null default 'pending',
  -- customer + address snapshot
  customer_name     text not null check (char_length(customer_name) between 2 and 120),
  email             text not null check (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' and char_length(email) <= 254),
  phone             text not null check (phone ~ '^\+[1-9][0-9]{7,14}$'),   -- E.164
  country           char(2) not null check (country ~ '^[A-Z]{2}$'),
  address_line1     text not null check (char_length(address_line1) between 3 and 200),
  address_line2     text check (char_length(address_line2) <= 200),
  city              text not null check (char_length(city) between 2 and 80),
  region            text check (char_length(region) <= 80),
  postal_code       text check (char_length(postal_code) <= 20),
  notes             text check (char_length(notes) <= 500),
  -- money (BDT, integer taka)
  shipping_zone_id  text not null references public.shipping_zones (id),
  subtotal_bdt      int not null check (subtotal_bdt >= 0),
  discount_bdt      int not null default 0 check (discount_bdt >= 0 and discount_bdt <= subtotal_bdt),
  shipping_bdt      int not null default 0 check (shipping_bdt >= 0),
  total_bdt         int not null,
  coupon_code       text,
  -- fulfilment
  courier           text,
  tracking_number   text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check (total_bdt = subtotal_bdt - discount_bdt + shipping_bdt),
  check (payment_method <> 'cod' or country = 'BD')
);
create index orders_created_idx on public.orders (created_at desc);
create index orders_status_idx  on public.orders (status, created_at desc);
create index orders_phone_idx   on public.orders (phone);

create table public.order_items (
  id              uuid primary key default gen_random_uuid(),
  order_id        uuid not null references public.orders (id) on delete cascade,
  product_id      uuid references public.products (id) on delete set null,
  variant_id      uuid references public.product_variants (id) on delete set null,
  product_name    text not null,
  colour          text not null,
  size            text not null,
  sku             text not null,
  unit_price_bdt  int not null check (unit_price_bdt > 0),
  quantity        int not null check (quantity between 1 and 10),
  line_total_bdt  int not null,
  created_at      timestamptz not null default now(),
  check (line_total_bdt = unit_price_bdt * quantity)
);
create index order_items_order_idx on public.order_items (order_id);

create table public.order_events (
  id          bigint generated always as identity primary key,
  order_id    uuid not null references public.orders (id) on delete cascade,
  status      public.order_status not null,
  note        text,
  created_at  timestamptz not null default now()
);
create index order_events_order_idx on public.order_events (order_id, created_at);

create table public.payments (
  id            uuid primary key default gen_random_uuid(),
  order_id      uuid not null references public.orders (id) on delete cascade,
  provider      public.payment_method not null,
  status        public.payment_status not null default 'pending',
  amount_bdt    int not null check (amount_bdt >= 0),
  currency      char(3) not null default 'BDT',
  provider_ref  text,                                 -- e.g. Stripe Checkout Session id
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (provider, provider_ref)
);
create index payments_order_idx on public.payments (order_id);

-- Webhook de-duplication: every provider event is processed at most once.
create table public.payment_events (
  provider     public.payment_method not null,
  event_id     text not null,
  payload      jsonb not null,
  received_at  timestamptz not null default now(),
  primary key (provider, event_id)
);

create table public.newsletter_subscribers (
  id          uuid primary key default gen_random_uuid(),
  email       text not null unique check (email = lower(email) and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  created_at  timestamptz not null default now()
);

-- ───────────── updated_at triggers ─────────────
do $$
declare t text;
begin
  foreach t in array array['profiles','categories','products','product_images','product_variants','inventory',
                           'shipping_zones','coupons','orders','payments'] loop
    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t);
  end loop;
end $$;

-- ═════ 20261118000002_rls.sql ═════
-- ═══════════════════════════════════════════════════════════════════════
-- Row Level Security
-- • Public (anon) can read the active catalogue and shipping zones only.
-- • Orders, payments, coupons, subscribers: staff only. Customers never
--   touch these tables directly; writes go through SECURITY DEFINER
--   functions callable only by the server (service_role).
-- ═══════════════════════════════════════════════════════════════════════

alter table public.profiles               enable row level security;
alter table public.categories             enable row level security;
alter table public.products               enable row level security;
alter table public.product_images         enable row level security;
alter table public.product_variants       enable row level security;
alter table public.inventory              enable row level security;
alter table public.shipping_zones         enable row level security;
alter table public.coupons                enable row level security;
alter table public.orders                 enable row level security;
alter table public.order_items            enable row level security;
alter table public.order_events           enable row level security;
alter table public.payments               enable row level security;
alter table public.payment_events         enable row level security;
alter table public.newsletter_subscribers enable row level security;

-- profiles: see yourself; admins see/manage everyone. No self-update (blocks role escalation).
create policy profiles_self_read  on public.profiles for select to authenticated using (id = auth.uid() or public.is_admin());
create policy profiles_admin_all  on public.profiles for all    to authenticated using (public.is_admin()) with check (public.is_admin());

-- catalogue: public read of active rows; staff full access
create policy categories_public_read on public.categories for select to anon, authenticated using (is_active or public.is_staff());
create policy categories_staff_write on public.categories for all    to authenticated using (public.is_staff()) with check (public.is_staff());

create policy products_public_read on public.products for select to anon, authenticated using (is_active or public.is_staff());
create policy products_staff_write on public.products for all    to authenticated using (public.is_staff()) with check (public.is_staff());

create policy images_public_read on public.product_images for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and (p.is_active or public.is_staff())));
create policy images_staff_write on public.product_images for all to authenticated using (public.is_staff()) with check (public.is_staff());

create policy variants_public_read on public.product_variants for select to anon, authenticated
  using ((is_active and exists (select 1 from public.products p where p.id = product_id and p.is_active)) or public.is_staff());
create policy variants_staff_write on public.product_variants for all to authenticated using (public.is_staff()) with check (public.is_staff());

create policy inventory_public_read on public.inventory for select to anon, authenticated using (true);
create policy inventory_staff_write on public.inventory for all to authenticated using (public.is_staff()) with check (public.is_staff());

create policy zones_public_read on public.shipping_zones for select to anon, authenticated using (is_active or public.is_staff());
create policy zones_admin_write on public.shipping_zones for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- staff-only tables
create policy coupons_staff        on public.coupons      for all to authenticated using (public.is_staff()) with check (public.is_staff());
create policy orders_staff         on public.orders       for all to authenticated using (public.is_staff()) with check (public.is_staff());
create policy order_items_staff    on public.order_items  for select to authenticated using (public.is_staff());
create policy order_events_staff   on public.order_events for all to authenticated using (public.is_staff()) with check (public.is_staff());
create policy payments_staff       on public.payments     for select to authenticated using (public.is_staff());
create policy payment_events_admin on public.payment_events for select to authenticated using (public.is_admin());
create policy newsletter_staff     on public.newsletter_subscribers for select to authenticated using (public.is_staff());
-- (no anon policies on these tables ⇒ anon sees and writes nothing)

-- ═════ 20261118000003_order_functions.sql ═════
-- ═══════════════════════════════════════════════════════════════════════
-- Order & payment functions
-- All money maths happens here, from database prices — never from the
-- client. Callable only by the server (service_role).
-- ═══════════════════════════════════════════════════════════════════════

-- ───────────── coupons ─────────────
create or replace function public.evaluate_coupon(p_code text, p_subtotal int, p_lock boolean default false)
returns table (coupon_id uuid, code text, discount_bdt int, label text, error text)
language plpgsql security definer set search_path = public as $$
declare c public.coupons;
begin
  if p_lock then
    select * into c from public.coupons where coupons.code = upper(trim(p_code)) for update;
  else
    select * into c from public.coupons where coupons.code = upper(trim(p_code));
  end if;

  if c.id is null or not c.is_active or c.starts_at > now() then
    return query select null::uuid, null::text, 0, null::text, 'That code isn''t valid.'; return;
  end if;
  if c.expires_at is not null and c.expires_at < now() then
    return query select null::uuid, null::text, 0, null::text, 'That code has expired.'; return;
  end if;
  if c.usage_limit is not null and c.used_count >= c.usage_limit then
    return query select null::uuid, null::text, 0, null::text, 'That code has reached its limit.'; return;
  end if;
  if p_subtotal < c.min_subtotal_bdt then
    return query select null::uuid, null::text, 0, null::text,
      format('Spend ৳ %s or more to use this code.', to_char(c.min_subtotal_bdt, 'FM999,999,999')); return;
  end if;

  return query select
    c.id, c.code,
    least(p_subtotal,
          case when c.kind = 'percent' then least(round(p_subtotal * c.value / 100.0)::int, coalesce(c.max_discount_bdt, 2147483647))
               else c.value end),
    case when c.kind = 'percent' then c.value || '% off' else '৳ ' || c.value || ' off' end,
    null::text;
end $$;

-- ───────────── cart pricing (shared by quote + place_order) ─────────────
-- p_lines: [{ "product": "<uuid | legacy id>", "size": "M", "qty": 2 }, ...]
create or replace function public.price_lines(p_lines jsonb)
returns table (variant_id uuid, product_id uuid, product_name text, colour text, size text, sku text,
               unit_price_bdt int, quantity int, available int)
language sql stable security definer set search_path = public as $$
  with req as (
    select l->>'product' as product_ref, l->>'size' as size, sum((l->>'qty')::int) as qty
    from jsonb_array_elements(p_lines) l
    group by 1, 2
  )
  select v.id, p.id, p.name, p.colour, v.size, v.sku,
         coalesce(v.price_override_bdt, p.sale_price_bdt, p.price_bdt),
         req.qty::int, coalesce(i.quantity, 0)
  from req
  join public.products p on (p.id::text = req.product_ref or p.legacy_id = req.product_ref) and p.is_active
  join public.product_variants v on v.product_id = p.id and v.size = req.size and v.is_active
  left join public.inventory i on i.variant_id = v.id
$$;

create or replace function public.quote_cart(p_lines jsonb, p_coupon text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_sub int; c record;
begin
  select coalesce(sum(unit_price_bdt * least(quantity, available)), 0) into v_sub from public.price_lines(p_lines);
  if p_coupon is null or trim(p_coupon) = '' then
    return jsonb_build_object('subtotal_bdt', v_sub);
  end if;
  select * into c from public.evaluate_coupon(p_coupon, v_sub, false);
  return jsonb_build_object('subtotal_bdt', v_sub, 'code', c.code, 'discount_bdt', c.discount_bdt, 'label', c.label, 'error', c.error);
end $$;

-- ───────────── place order (atomic) ─────────────
create or replace function public.place_order(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_existing  public.orders;
  v_order     public.orders;
  v_customer  jsonb := p->'customer';
  v_country   text  := upper(v_customer->>'country');
  v_method    public.payment_method := (p->>'payment_method')::public.payment_method;
  v_zone      public.shipping_zones;
  v_line      record;
  v_lines     int := 0;
  v_requested int;
  v_sub       int := 0;
  v_coupon    record;
  v_coupon_code text;
  v_discount  int := 0;
  v_ship      int;
  v_number    text;
begin
  -- Idempotency: a retried submit returns the original order.
  if p->>'idempotency_key' is not null then
    select * into v_existing from public.orders where idempotency_key = p->>'idempotency_key';
    if v_existing.id is not null then
      return jsonb_build_object('order_id', v_existing.id, 'order_number', v_existing.order_number,
                                'total_bdt', v_existing.total_bdt, 'payment_method', v_existing.payment_method, 'duplicate', true);
    end if;
  end if;

  -- Zone must agree with the country (server never trusts a mismatched pair).
  select * into v_zone from public.shipping_zones where id = p->>'shipping_zone_id' and is_active;
  if v_zone.id is null
     or (v_country = 'BD' and v_zone.id not in ('dhaka', 'outside-dhaka'))
     or (v_country <> 'BD' and v_zone.id <> 'international') then
    raise exception 'INVALID_ZONE' using errcode = 'P0001';
  end if;
  if v_method = 'cod' and v_country <> 'BD' then
    raise exception 'COD_BD_ONLY' using errcode = 'P0001';
  end if;

  select count(*) into v_requested from (
    select distinct l->>'product', l->>'size' from jsonb_array_elements(p->'lines') l) s;
  if v_requested = 0 or v_requested > 50 then
    raise exception 'EMPTY_CART' using errcode = 'P0001';
  end if;

  -- Lock stock rows in a fixed order to avoid deadlocks, then validate.
  perform 1 from public.inventory i
   where i.variant_id in (select variant_id from public.price_lines(p->'lines'))
   order by i.variant_id for update;

  for v_line in select * from public.price_lines(p->'lines') loop
    v_lines := v_lines + 1;
    if v_line.quantity < 1 or v_line.quantity > 10 then
      raise exception 'INVALID_QTY:%', v_line.sku using errcode = 'P0001';
    end if;
    if v_line.available < v_line.quantity then
      raise exception 'OUT_OF_STOCK:%', v_line.sku using errcode = 'P0001';
    end if;
    v_sub := v_sub + v_line.unit_price_bdt * v_line.quantity;
  end loop;
  if v_lines <> v_requested then
    raise exception 'UNKNOWN_ITEM' using errcode = 'P0001';
  end if;

  if nullif(trim(p->>'coupon_code'), '') is not null then
    select * into v_coupon from public.evaluate_coupon(p->>'coupon_code', v_sub, true);
    if v_coupon.error is not null then
      raise exception 'COUPON:%', v_coupon.error using errcode = 'P0001';
    end if;
    v_discount := v_coupon.discount_bdt;
    v_coupon_code := v_coupon.code;
    update public.coupons set used_count = used_count + 1 where id = v_coupon.coupon_id;
  end if;

  v_ship := case when v_zone.free_over_bdt is not null and (v_sub - v_discount) >= v_zone.free_over_bdt then 0 else v_zone.fee_bdt end;

  -- Human-friendly, non-sequential order number; retry on the rare collision.
  loop
    v_number := 'DM-' || to_char(now() at time zone 'Asia/Dhaka', 'YYMMDD') || '-' ||
                upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));
    exit when not exists (select 1 from public.orders where order_number = v_number);
  end loop;

  insert into public.orders (
    order_number, idempotency_key, payment_method, customer_name, email, phone, country,
    address_line1, address_line2, city, region, postal_code, notes,
    shipping_zone_id, subtotal_bdt, discount_bdt, shipping_bdt, total_bdt, coupon_code
  ) values (
    v_number, p->>'idempotency_key', v_method,
    v_customer->>'name', lower(v_customer->>'email'), v_customer->>'phone', v_country,
    v_customer->>'address_line1', nullif(v_customer->>'address_line2', ''), v_customer->>'city',
    nullif(v_customer->>'region', ''), nullif(v_customer->>'postal_code', ''), nullif(v_customer->>'notes', ''),
    v_zone.id, v_sub, v_discount, v_ship, v_sub - v_discount + v_ship, v_coupon_code
  ) returning * into v_order;

  insert into public.order_items (order_id, product_id, variant_id, product_name, colour, size, sku, unit_price_bdt, quantity, line_total_bdt)
  select v_order.id, l.product_id, l.variant_id, l.product_name, l.colour, l.size, l.sku, l.unit_price_bdt, l.quantity, l.unit_price_bdt * l.quantity
  from public.price_lines(p->'lines') l;

  update public.inventory i set quantity = i.quantity - l.quantity
  from public.price_lines(p->'lines') l where i.variant_id = l.variant_id;

  insert into public.payments (order_id, provider, amount_bdt) values (v_order.id, v_method, v_order.total_bdt);
  insert into public.order_events (order_id, status, note)
  values (v_order.id, 'pending', case when v_method = 'cod' then 'Order received — we will call to confirm.' else 'Awaiting payment.' end);

  return jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number,
                            'total_bdt', v_order.total_bdt, 'payment_method', v_order.payment_method, 'duplicate', false);
end $$;

-- ───────────── cancel + restock (internal) ─────────────
create or replace function public.cancel_order(p_order_id uuid, p_reason text)
returns boolean language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  select * into o from public.orders where id = p_order_id for update;
  if o.id is null or o.status in ('cancelled', 'refunded', 'shipped', 'delivered') then return false; end if;
  update public.inventory i set quantity = i.quantity + oi.quantity
    from public.order_items oi where oi.order_id = o.id and oi.variant_id = i.variant_id;
  if o.coupon_code is not null then
    update public.coupons set used_count = greatest(used_count - 1, 0) where code = o.coupon_code;
  end if;
  update public.orders set status = 'cancelled',
         payment_status = case when payment_status = 'paid' then payment_status else 'cancelled' end
   where id = o.id;
  insert into public.order_events (order_id, status, note) values (o.id, 'cancelled', p_reason);
  return true;
end $$;

-- Release stock held by online-payment orders that were never paid.
-- Schedule every 10 minutes with pg_cron in production (see README).
create or replace function public.release_unpaid_orders(p_older_than interval default '45 minutes')
returns int language plpgsql security definer set search_path = public as $$
declare r record; n int := 0;
begin
  for r in select id from public.orders
           where payment_method <> 'cod' and payment_status = 'pending' and status = 'pending'
             and created_at < now() - p_older_than
  loop
    if public.cancel_order(r.id, 'Payment not completed in time.') then n := n + 1; end if;
  end loop;
  return n;
end $$;

-- ───────────── payment webhooks (idempotent) ─────────────
-- p_outcome: 'paid' | 'failed' | 'expired'
create or replace function public.apply_payment_event(
  p_provider public.payment_method, p_event_id text, p_payload jsonb,
  p_provider_ref text, p_outcome text, p_amount_bdt int)
returns text language plpgsql security definer set search_path = public as $$
declare pay public.payments; o public.orders; inserted int;
begin
  insert into public.payment_events (provider, event_id, payload) values (p_provider, p_event_id, p_payload)
  on conflict do nothing;
  get diagnostics inserted = row_count;
  if inserted = 0 then return 'duplicate'; end if;

  select * into pay from public.payments where provider = p_provider and provider_ref = p_provider_ref for update;
  if pay.id is null then return 'unknown_payment'; end if;
  select * into o from public.orders where id = pay.order_id for update;

  if p_outcome = 'paid' then
    if p_amount_bdt is distinct from pay.amount_bdt then
      update public.payments set status = 'failed' where id = pay.id;
      insert into public.order_events (order_id, status, note) values (o.id, o.status, 'Payment amount mismatch — held for review.');
      return 'amount_mismatch';
    end if;
    if pay.status = 'paid' then return 'already_paid'; end if;
    update public.payments set status = 'paid' where id = pay.id;
    if o.status = 'cancelled' then
      -- Paid after the hold expired: keep it visible for staff to resolve.
      update public.orders set payment_status = 'paid' where id = o.id;
      insert into public.order_events (order_id, status, note) values (o.id, 'cancelled', 'Payment arrived after cancellation — refund or reinstate.');
      return 'paid_after_cancel';
    end if;
    update public.orders set payment_status = 'paid', status = 'confirmed' where id = o.id;
    insert into public.order_events (order_id, status, note) values (o.id, 'confirmed', 'Payment received.');
    return 'paid';
  elsif p_outcome in ('failed', 'expired') then
    if pay.status = 'paid' then return 'already_paid'; end if;
    update public.payments set status = case when p_outcome = 'failed' then 'failed'::public.payment_status else 'cancelled'::public.payment_status end where id = pay.id;
    perform public.cancel_order(o.id, case when p_outcome = 'failed' then 'Payment failed.' else 'Payment session expired.' end);
    return p_outcome;
  end if;
  return 'ignored';
end $$;

-- ───────────── guest order tracking ─────────────
-- Requires order number AND the phone used at checkout. Returns no address/email.
create or replace function public.track_order(p_order_number text, p_phone text)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'order_number', o.order_number, 'status', o.status, 'payment_status', o.payment_status,
    'payment_method', o.payment_method, 'created_at', o.created_at, 'total_bdt', o.total_bdt,
    'courier', o.courier, 'tracking_number', o.tracking_number,
    'items', (select jsonb_agg(jsonb_build_object('name', product_name, 'size', size, 'qty', quantity) order by created_at)
              from public.order_items where order_id = o.id),
    'events', (select jsonb_agg(jsonb_build_object('status', status, 'note', note, 'at', created_at) order by created_at)
               from public.order_events where order_id = o.id))
  from public.orders o
  where o.order_number = upper(trim(p_order_number)) and o.phone = p_phone
$$;

-- ───────────── lock down execution ─────────────
do $$
declare f text;
begin
  foreach f in array array[
    'public.evaluate_coupon(text,int,boolean)', 'public.price_lines(jsonb)', 'public.quote_cart(jsonb,text)',
    'public.place_order(jsonb)', 'public.cancel_order(uuid,text)', 'public.release_unpaid_orders(interval)',
    'public.apply_payment_event(public.payment_method,text,jsonb,text,text,int)', 'public.track_order(text,text)'] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end $$;
-- is_staff / is_admin are evaluated inside RLS policies, including for anon
-- (where they simply return false), so every API role must be able to run them.
revoke all on function public.is_staff(), public.is_admin() from public;
grant execute on function public.is_staff(), public.is_admin() to anon, authenticated, service_role;
revoke all on function public.handle_new_user() from public, anon, authenticated;

-- ═════ 20261119000004_admin.sql ═════
-- ═══════════════════════════════════════════════════════════════════════
-- Admin dashboard support
-- Admin pages use the signed-in staff member's own JWT, so every read and
-- write below is still filtered by RLS / is_staff() checks in the database —
-- hiding a button in the UI is never the only protection.
-- ═══════════════════════════════════════════════════════════════════════

-- ───────────── order status changes ─────────────
create or replace function public.staff_update_order(
  p_order_id uuid, p_status public.order_status, p_note text default null,
  p_courier text default null, p_tracking text default null)
returns public.orders
language plpgsql security definer set search_path = public as $$
declare o public.orders;
begin
  if not public.is_staff() then raise exception 'FORBIDDEN' using errcode = '42501'; end if;
  select * into o from public.orders where id = p_order_id for update;
  if o.id is null then raise exception 'NOT_FOUND' using errcode = 'P0002'; end if;

  -- Allowed transitions
  if not (
       (o.status = 'pending'    and p_status in ('confirmed', 'processing', 'cancelled'))
    or (o.status = 'confirmed'  and p_status in ('processing', 'shipped', 'cancelled'))
    or (o.status = 'processing' and p_status in ('shipped', 'cancelled'))
    or (o.status = 'shipped'    and p_status in ('delivered'))
    or (o.status = 'delivered'  and p_status in ('refunded'))
    or (o.status = 'cancelled'  and p_status in ('refunded') and o.payment_status = 'paid')
    or (o.status = p_status)
  ) then
    raise exception 'BAD_TRANSITION:% → %', o.status, p_status using errcode = 'P0001';
  end if;
  if p_status = 'shipped' and coalesce(nullif(trim(p_tracking), ''), o.tracking_number) is null then
    raise exception 'TRACKING_REQUIRED' using errcode = 'P0001';
  end if;

  if p_status = 'cancelled' and o.status <> 'cancelled' then
    perform public.cancel_order(o.id, coalesce(nullif(trim(p_note), ''), 'Cancelled by staff.'));
  else
    update public.orders set
      status          = p_status,
      courier         = coalesce(nullif(trim(p_courier), ''), courier),
      tracking_number = coalesce(nullif(trim(p_tracking), ''), tracking_number),
      -- Cash on delivery is collected when the parcel is delivered.
      payment_status  = case
                          when p_status = 'delivered' and payment_method = 'cod' then 'paid'::public.payment_status
                          when p_status = 'refunded' then 'refunded'::public.payment_status
                          else payment_status end
    where id = o.id;
    if p_status = 'delivered' and o.payment_method = 'cod' then
      update public.payments set status = 'paid' where order_id = o.id and provider = 'cod';
    end if;
    if p_status <> o.status or nullif(trim(p_note), '') is not null then
      insert into public.order_events (order_id, status, note) values (o.id, p_status, nullif(trim(p_note), ''));
    end if;
  end if;

  select * into o from public.orders where id = p_order_id;
  return o;
end $$;

-- ───────────── dashboard numbers (runs with the caller's RLS) ─────────────
create or replace function public.staff_dashboard(p_days int default 30)
returns jsonb language sql stable security invoker set search_path = public as $$
  with live as (select * from public.orders where status not in ('cancelled', 'refunded'))
  select jsonb_build_object(
    'revenue_bdt',   coalesce((select sum(total_bdt) from live), 0),
    'orders',        (select count(*) from public.orders),
    'open_orders',   (select count(*) from public.orders where status in ('pending', 'confirmed', 'processing')),
    'customers',     (select count(distinct phone) from public.orders),
    'products',      (select count(*) from public.products),
    'daily', (
      select coalesce(jsonb_agg(jsonb_build_object('day', d::date, 'revenue_bdt', coalesce(r.rev, 0), 'orders', coalesce(r.n, 0)) order by d), '[]'::jsonb)
      from generate_series((now() at time zone 'Asia/Dhaka')::date - (p_days - 1), (now() at time zone 'Asia/Dhaka')::date, interval '1 day') d
      left join (select (created_at at time zone 'Asia/Dhaka')::date as od, sum(total_bdt) as rev, count(*) as n from live group by 1) r on r.od = d::date),
    'low_stock', (
      select coalesce(jsonb_agg(x order by x->>'quantity'), '[]'::jsonb) from (
        select jsonb_build_object('product', p.name, 'product_id', p.id, 'size', v.size, 'sku', v.sku, 'quantity', i.quantity) x
        from public.inventory i join public.product_variants v on v.id = i.variant_id join public.products p on p.id = v.product_id
        where i.quantity <= i.low_stock_threshold and v.is_active and p.is_active
        order by i.quantity limit 12) s),
    'top_products', (
      select coalesce(jsonb_agg(t order by (t->>'units')::int desc), '[]'::jsonb) from (
        select jsonb_build_object('name', oi.product_name, 'units', sum(oi.quantity), 'revenue_bdt', sum(oi.line_total_bdt)) t
        from public.order_items oi join live o on o.id = oi.order_id
        group by oi.product_name order by sum(oi.quantity) desc limit 5) s)
  )
$$;

-- ───────────── customers (guest checkout ⇒ grouped by phone) ─────────────
create or replace view public.staff_customers with (security_invoker = true) as
  select o.phone,
         (array_agg(o.customer_name order by o.created_at desc))[1] as name,
         (array_agg(o.email order by o.created_at desc))[1]          as email,
         (array_agg(o.city order by o.created_at desc))[1]           as city,
         o.country,
         count(*)                                                     as orders,
         coalesce(sum(o.total_bdt) filter (where o.status not in ('cancelled', 'refunded')), 0) as spent_bdt,
         max(o.created_at)                                            as last_order_at
  from public.orders o
  group by o.phone, o.country;

-- ───────────── grants ─────────────
revoke all on function public.staff_update_order(uuid, public.order_status, text, text, text) from public, anon;
grant execute on function public.staff_update_order(uuid, public.order_status, text, text, text) to authenticated, service_role;
revoke all on function public.staff_dashboard(int) from public, anon;
grant execute on function public.staff_dashboard(int) to authenticated, service_role;
revoke all on public.staff_customers from anon;
grant select on public.staff_customers to authenticated, service_role;

-- ───────────── product image storage (Supabase only) ─────────────
do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'storage') then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('product-images', 'product-images', true, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'image/avif'])
    on conflict (id) do nothing;

    execute $p$create policy "product images: public read" on storage.objects for select to anon, authenticated
                using (bucket_id = 'product-images')$p$;
    execute $p$create policy "product images: staff upload" on storage.objects for insert to authenticated
                with check (bucket_id = 'product-images' and public.is_staff())$p$;
    execute $p$create policy "product images: staff update" on storage.objects for update to authenticated
                using (bucket_id = 'product-images' and public.is_staff())$p$;
    execute $p$create policy "product images: staff delete" on storage.objects for delete to authenticated
                using (bucket_id = 'product-images' and public.is_staff())$p$;
  end if;
end $$;

-- ═════ 20261119000005_bangla_content.sql ═════
-- Optional Bangla content for products and categories.
-- Empty values fall back to English on the storefront.
alter table public.products
  add column if not exists name_bn        text check (char_length(name_bn) <= 160),
  add column if not exists colour_bn      text check (char_length(colour_bn) <= 60),
  add column if not exists description_bn text check (char_length(description_bn) <= 3000),
  add column if not exists details_bn     text[] not null default '{}';

alter table public.categories
  add column if not exists name_bn text check (char_length(name_bn) <= 80);

-- ═════ 20261119000006_contact_messages.sql ═════
-- Messages sent from the storefront Contact page.
-- Inserted only by the server (service role) after validation + rate limiting;
-- readable and updatable by staff only.
create table public.contact_messages (
  id            uuid primary key default gen_random_uuid(),
  name          text not null check (char_length(name) between 2 and 120),
  email         text not null check (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' and char_length(email) <= 254),
  phone         text check (char_length(phone) <= 24),
  topic         text not null check (topic in ('order', 'sizing', 'returns', 'wholesale', 'other')),
  order_number  text check (order_number ~ '^DM-\d{6}-[0-9A-F]{6}$'),
  message       text not null check (char_length(message) between 10 and 2000),
  locale        text not null default 'en' check (locale in ('en', 'bn')),
  status        text not null default 'new' check (status in ('new', 'replied', 'closed')),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index contact_messages_status_idx on public.contact_messages (status, created_at desc);
create trigger set_updated_at before update on public.contact_messages for each row execute function public.set_updated_at();

alter table public.contact_messages enable row level security;
create policy contact_messages_staff_read   on public.contact_messages for select to authenticated using (public.is_staff());
create policy contact_messages_staff_update on public.contact_messages for update to authenticated using (public.is_staff()) with check (public.is_staff());
-- No insert/delete policies: anon and customers can't write here directly.

-- ═════ 20261119000007_store_settings.sql ═════
-- Store-wide settings that admins can change without a redeploy.
-- Only keys listed as public are readable by visitors; everything else is admin-only.
create table public.store_settings (
  key         text primary key check (key ~ '^[a-z_]+$'),
  value       jsonb not null,
  is_public   boolean not null default false,
  updated_at  timestamptz not null default now()
);
create trigger set_updated_at before update on public.store_settings for each row execute function public.set_updated_at();

alter table public.store_settings enable row level security;
create policy store_settings_public_read on public.store_settings for select to anon, authenticated using (is_public or public.is_admin());
create policy store_settings_admin_write on public.store_settings for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Display-only USD rate: how many taka one US dollar is worth. Payments are always charged in BDT.
insert into public.store_settings (key, value, is_public)
values ('usd_rate', jsonb_build_object('bdt_per_usd', 122), true)
on conflict (key) do nothing;

-- Sanity bounds so a typo can't show absurd prices.
alter table public.store_settings add constraint usd_rate_sane check (
  key <> 'usd_rate' or ((value->>'bdt_per_usd')::numeric between 50 and 500)
);

-- ═════ 20261119000008_rate_limits.sql ═════
-- Shared rate limiting for serverless deployments, where in-memory counters
-- don't survive between requests. Fixed windows, one row per key per window.
create table public.rate_limits (
  key           text not null check (char_length(key) <= 200),
  window_start  timestamptz not null,
  count         int not null default 0,
  primary key (key, window_start)
);
alter table public.rate_limits enable row level security; -- no policies: server only

create or replace function public.hit_rate_limit(p_key text, p_limit int, p_window_seconds int)
returns boolean language plpgsql security definer set search_path = public as $$
declare
  v_start timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  v_count int;
begin
  insert into public.rate_limits (key, window_start, count) values (p_key, v_start, 1)
  on conflict (key, window_start) do update set count = rate_limits.count + 1
  returning count into v_count;
  return v_count <= p_limit;
end $$;

create or replace function public.prune_rate_limits() returns int
language sql security definer set search_path = public as $$
  with d as (delete from public.rate_limits where window_start < now() - interval '1 day' returning 1)
  select count(*)::int from d
$$;

revoke all on function public.hit_rate_limit(text, int, int), public.prune_rate_limits() from public, anon, authenticated;
grant execute on function public.hit_rate_limit(text, int, int), public.prune_rate_limits() to service_role;

