values ('p1', 'cloud-cashmere-cardigan-ivory', 'Cloud Cashmere Cardigan', 'A cropped V-neck cardigan in brushed Mongolian cashmere. Featherlight, gently boxy, finished with mother-of-pearl buttons and a soft rib at cuff and hem.', array['100% Grade-A cashmere', 'Mother-of-pearl buttons', 'Relaxed, cropped fit', 'Hand wash cold, dry flat']::text[], 'ক্লাউড ক্যাশমিয়ার কার্ডিগান', 'আইভরি', 'ব্রাশড মঙ্গোলিয়ান ক্যাশমিয়ারে তৈরি ক্রপড ভি-নেক কার্ডিগান। পালকের মতো হালকা, একটু বক্সি গড়ন, মাদার-অফ-পার্ল বোতাম আর হাতা ও নিচে নরম রিব।', array['১০০% গ্রেড-এ ক্যাশমিয়ার', 'মাদার-অফ-পার্ল বোতাম', 'ঢিলেঢালা, ক্রপড ফিট', 'ঠান্ডা পানিতে হাতে ধুয়ে সমতলে শুকান']::text[], (select id from public.categories where slug = 'hoodies'), 'women', 'Ivory', '#f3eee4', 14500, null, true, false, 88, '2026-11-10')
on conflict (legacy_id) do update set name = excluded.name, description = excluded.description, name_bn = excluded.name_bn, colour_bn = excluded.colour_bn, description_bn = excluded.description_bn, details_bn = excluded.details_bn, price_bdt = excluded.price_bdt, sale_price_bdt = excluded.sale_price_bdt;
insert into public.product_images (product_id, src, alt, fit, object_position, sort) select id, '/images/products/cashmere-cardigan.webp', 'Ivory cashmere cardigan', 'contain', null, 0 from public.products where legacy_id = 'p1' and not exists (select 1 from public.product_images pi join public.products pp on pp.id = pi.product_id where pp.legacy_id = 'p1' and pi.src = '/images/products/cashmere-cardigan.webp');
insert into public.product_images (product_id, src, alt, fit, object_position, sort) select id, '/images/editorial/cardigan-desert.webp', 'Ivory cashmere cardigan floating over desert dunes', 'cover', '78% 50%', 1 from public.products where legacy_id = 'p1' and not exists (select 1 from public.product_images pi join public.products pp on pp.id = pi.product_id where pp.legacy_id = 'p1' and pi.src = '/images/editorial/cardigan-desert.webp');
