values ('p2', 'pleated-column-dress-sienna', 'Pleated Column Dress', 'A mock-neck column dress in knife-pleated georgette, with a layered cropped top panel that floats over the skirt as you move.', array['100% recycled polyester georgette', 'Permanent knife pleats', 'Unlined, pull-on', 'Machine wash delicate']::text[], 'প্লিটেড কলাম ড্রেস', 'সিয়েনা', 'নাইফ-প্লিটেড জর্জেটে মক-নেক কলাম ড্রেস, ওপরে একটি ক্রপড প্যানেল যা চলার সাথে স্কার্টের ওপর ভেসে থাকে।', array['১০০% রিসাইকেলড পলিয়েস্টার জর্জেট', 'স্থায়ী নাইফ প্লিট', 'লাইনিং ছাড়া, সহজে পরা যায়', 'ডেলিকেট মোডে মেশিনে ধোয়া যায়']::text[], (select id from public.categories where slug = 'dresses'), 'women', 'Sienna', '#b97a4a', 16800, null, true, false, 74, '2026-11-08')
