values ('p3', 'knit-block-pump-sand', 'Knit Block Pump', 'A square-toe pump with a seamless recycled-knit upper on a sculpted 5 cm block heel. Soft enough for all day, sharp enough for evening.', array['Knit from recycled bottles', '5 cm sculpted block heel', 'Cushioned removable insole', 'Machine washable upper']::text[], 'নিট ব্লক পাম্প', 'স্যান্ড', 'স্কয়ার-টো পাম্প, সেলাইবিহীন রিসাইকেলড নিটের উপরিভাগ আর ৫ সেমি ভাস্কর্য-আকৃতির ব্লক হিল। সারাদিন আরামে পরা যায়, সন্ধ্যার জন্যও মানানসই।', array['রিসাইকেলড বোতল থেকে বোনা', '৫ সেমি ব্লক হিল', 'কুশনযুক্ত খোলা যায় এমন ইনসোল', 'উপরিভাগ মেশিনে ধোয়া যায়']::text[], (select id from public.categories where slug = 'shoes'), 'women', 'Sand', '#e6d8bf', 7900, 6900, true, false, 91, '2026-11-05')
