values ('p4', 'brushed-crew-sweater-heather', 'Brushed Crew Sweater', 'A heavyweight loopback-cotton crew, brushed soft on the inside, with a dropped shoulder and generous body. The sweater you''ll reach for first.', array['100% organic cotton loopback, 420 gsm', 'Brushed interior', 'Relaxed fit', 'Machine wash cold']::text[], 'ব্রাশড ক্রু সোয়েটার', 'হেদার গ্রে', 'ভারী লুপব্যাক কটনের ক্রু সোয়েটার, ভেতরে নরম ব্রাশ করা, নামানো কাঁধ আর ঢিলেঢালা গড়ন। যে সোয়েটার আপনি সবার আগে হাতে নেবেন।', array['১০০% অর্গানিক কটন লুপব্যাক, ৪২০ জিএসএম', 'ভেতরে ব্রাশ করা', 'রিল্যাক্সড ফিট', 'ঠান্ডা পানিতে মেশিনে ধোয়া যায়']::text[], (select id from public.categories where slug = 'hoodies'), 'men', 'Heather Grey', '#c9c7c3', 5900, null, false, true, 97, '2026-09-20')
