values ('p5', 'heritage-trench-coat-stone', 'Heritage Trench Coat', 'A double-breasted trench in water-resistant cotton gabardine, with storm flap, epaulettes and a belted waist. Cut long and worn loose.', array['100% cotton gabardine, water-resistant', 'Horn-effect buttons', 'Detachable belt', 'Dry clean only']::text[], 'হেরিটেজ ট্রেঞ্চ কোট', 'স্টোন', 'পানি-প্রতিরোধী কটন গ্যাবার্ডিনে ডাবল-ব্রেস্টেড ট্রেঞ্চ, স্টর্ম ফ্ল্যাপ, এপোলেট আর বেল্টসহ কোমর। লম্বা কাট, ঢিলেঢালা পরার জন্য।', array['১০০% কটন গ্যাবার্ডিন, পানি-প্রতিরোধী', 'হর্ন-ধাঁচের বোতাম', 'খোলা যায় এমন বেল্ট', 'শুধু ড্রাই ক্লিন']::text[], (select id from public.categories where slug = 'jackets'), 'unisex', 'Stone', '#cdb48e', 22500, null, false, true, 85, '2026-08-15')
