values ('p7', 'pleated-maxi-dress-sand', 'Pleated Maxi Dress', 'A high-neck maxi dress with a fitted knit bodice and a full sunray-pleated skirt that catches every breeze.', array['Knit bodice, pleated chiffon skirt', 'Concealed back zip', 'Fully lined skirt', 'Dry clean only']::text[], 'প্লিটেড ম্যাক্সি ড্রেস', 'স্যান্ড', 'হাই-নেক ম্যাক্সি ড্রেস, ফিটেড নিট বডিস আর পুরো সানরে-প্লিটেড স্কার্ট যা প্রতিটি বাতাসে দোলে।', array['নিট বডিস, প্লিটেড শিফন স্কার্ট', 'পেছনে লুকানো চেইন', 'স্কার্টে পূর্ণ লাইনিং', 'শুধু ড্রাই ক্লিন']::text[], (select id from public.categories where slug = 'dresses'), 'women', 'Sand', '#d8c3a5', 17200, 14900, false, true, 80, '2026-07-30')
on conflict (legacy_id) do update set name = excluded.name, description = excluded.description, name_bn = excluded.name_bn, colour_bn = excluded.colour_bn, description_bn = excluded.description_bn, details_bn = excluded.details_bn, price_bdt = excluded.price_bdt, sale_price_bdt = excluded.sale_price_bdt;
insert into public.product_images (product_id, src, alt, fit, object_position, sort) select id, '/images/editorial/pleated-dunes.webp', 'Sand pleated maxi dress on a stone plinth', 'cover', '55% 40%', 0 from public.products where legacy_id = 'p7' and not exists (select 1 from public.product_images pi join public.products pp on pp.id = pi.product_id where pp.legacy_id = 'p7' and pi.src = '/images/editorial/pleated-dunes.webp');
