insert into public.inventory (variant_id, quantity) select id, 3 from public.product_variants where sku = 'DM-P7-M' on conflict (variant_id) do nothing;
insert into public.product_variants (product_id, size, sku) select id, 'L', 'DM-P7-L' from public.products where legacy_id = 'p7' on conflict (sku) do nothing;
